    "care": "업데이트는 강제가 아니에요. 줄이 빨간색이면 aimusiclist.com 이 지원하는 버전보다 낮다는 뜻이니 꼭 업데이트하세요. 업데이트해도 곡과 설정은 그대로예요. PHP판은 이 줄에 바로 업데이트 버튼이 있어요.",
