    "when": "시간 날 때 고쳐요. aimusiclist.com 에서 듣는 사람이 자기 언어의 곡을 찾기 쉬워져요.",
    "click": "안내일 뿐이에요. [[지금 지정]]을 누르면 한꺼번에 고칠 수 있어요.",
