    "what": "10분을 기다리지 않고 Cloudflare 에서 사용량 숫자를 지금 다시 읽는 버튼이에요.",
    "when": "곡을 많이 올린 뒤나 새 사용량 키를 넣은 뒤에 눌러요.",
    "click": "잠시 뒤 막대가 바뀌고, 제목 옆의 시각도 바뀌어요.",
    "care": "Cloudflare 쪽 숫자도 조금 늦게 바뀔 수 있어요. 그래서 새로 읽어도 한동안 같아 보일 수 있어요.",
