    "click": "글자를 쓰는 대로 바로 목록이 바뀌어요. 아무것도 저장되거나 바뀌지 않아요. 칸을 비우면 모든 곡이 다시 보여요.",
    "care": "제목만 찾아요. 장르나 아티스트 이름으로는 찾지 않아요. 영어 대문자·소문자는 가리지 않아요. 표 맨 위 [[보이는 곡 모두 선택]] 칸은 찾은 뒤 남은 곡만 골라요.",
