    "care": "곡이 10곡 이상이면 적어도 10곡은 공개해야 해서, 그보다 더 끌 수는 없어요. 곡이 10곡보다 적으면 모두 공개해 두어야 해요(열 제목 아래 작은 글이 어느 규칙인지 알려 줘요). 흐린 스위치는 공개 앨범(공개 예약 포함)에 든 곡이에요. 앨범을 먼저 비공개로 바꾸세요.",
