    "care": "공개 곡은 적어도 10곡이어야 해요(전체가 10곡보다 적으면 모두). 그래서 체크를 풀어도 새 곡이 공개될 수 있고, 체크를 풀고 저장하면 막힐 수 있어요. 공개 앨범에 든 곡은 체크를 풀어도 바뀌지 않아요. 앨범을 먼저 비공개로 해야 해요.",
