    "care": "목록에는 20개까지 들어가요. 넘는 파일은 빠져요. MP3·M4A는 15MB 이하여야 해요. WAV는 여기서 320kbps MP3로 바꿔 올리는데, 바꾼 뒤에도 15MB 이하여야 해요(약 6분 30초까지). 길이는 30초~15분이어야 해요.",
