    "when": "AI 안내대로 곡 이름을 지었다면 켜 두세요. 괄호가 진짜 제목의 일부라면 꺼 두세요.",
    "click": "바꾸면 바로 목록을 다시 읽어요. 내가 손으로 고친 파일은 그대로 두고, 손대지 않은 파일만 다시 채워요. 켬·끔은 이 브라우저가 기억해요.",
    "care": "“;” 앞은 장르예요(첫 번째가 메인 장르). 뒤는 분위기와 언어 코드예요. 모르는 낱말은 건너뛰고 회색 글로 알려 줘요. (Live)나 (feat. X) 같은 괄호는 제목에 그대로 남아요.",
