    "click": "날짜·시각을 고르는 칸이 열려요. 시각은 지금 쓰는 기기의 시간대 기준이에요. [[앨범 저장]]을 누르면 목록에 공개 예정 시각이 보여요. 그 시각 전에는 내 사이트와 aimusiclist.com 모두에서 숨겨져 있어요. 시각이 지나면 1분쯤 안에 두 곳에 나타나요.",
