    "click": "어떻게 됐는지 알림이 떠요. 지금 공개됐는지, 정한 시각에 공개될지, 아니면 음원 있는 곡이 6~35곡 필요해서 비공개로 저장됐는지 알려 줘요. 그다음 아래 목록에 앨범이 보여요. 공개 앨범은 1~2분 뒤 aimusiclist.com 에도 나타나요.",
    "care": "제목은 꼭 있어야 해요. 날짜·시각을 골랐다면 지금보다 뒤여야 해요. 내 사이트의 공개 곡이 10곡보다 적어지게 되는 경우처럼 저장이 막힐 때도 있어요. 그때는 빨간 글로 이유를 알려 줘요.",
    "like": "다 만든 음반을 포장해서 진열대에 올려놓는 거예요."
