    "what": "이 앨범에 담은 곡을 한 번에 모두 빼는 버튼이에요. 처음부터 다시 고를 수 있어요.",
    "when": "곡 목록을 처음부터 다시 짜고 싶을 때 써요.",
    "click": "먼저 한 번 물어봐요. [확인]을 누르면 오른쪽이 비고 곡들이 왼쪽 목록으로 돌아가요. [[앨범 저장]]을 눌러야 저장돼요. 마음이 바뀌면 [[취소]]를 눌러 앨범을 원래대로 둘 수 있어요.",
