    "click": "창에서 [[이미지 저장]]을 누르면 새 커버가 여기에 보이고 '새 커버'라는 글이 붙어요. 아직 저장된 건 아니에요. [[앨범 저장]]을 눌러야 저장돼요. 옆의 [[취소]]를 누르면 새 그림을 버려요.",
