    "click": "새 버전을 검사한 뒤 옛 버전과 바꿔 끼워요. 지금 쓰는 스킨이 무엇인지는 바뀌지 않아요. 이 스킨을 쓰고 있다면 방문자 화면에 30초쯤 안에 새 버전이 보여요.",
    "care": "스킨 디자인만 바뀌어요. 사이트 자체의 업데이트와는 따로예요. 내가 직접 올린 스킨에는 이 버튼이 나오지 않아요.",
