    "when": "나만의 스킨을 만들고 싶을 때 써요. 받은 파일을 무료 AI 채팅(ChatGPT, Claude)에 주고 색이나 배치를 바꿔 달라고 하면 돼요.",
    "click": "브라우저가 스킨 파일을 저장해요. 내 사이트는 아무것도 바뀌지 않아요.",
    "care": "기본 스킨 자체는 고칠 수 없어요. 고친 파일은 새 이름으로 **스킨 올리기**에서 올린 뒤 [[이 스킨 쓰기]]를 눌러요.",
