    "when": "더 쓰지 않는 스킨이 있을 때, 또는 스킨이 20개가 차서 새 스킨 자리가 필요할 때 써요.",
    "click": "정말 지울지 한 번 물어봐요. 확인하면 바로 사라져요. 지금 쓰던 스킨이었다면 사이트는 라이트 스킨으로 바뀌어요.",
