    "click": "스킨을 검사하고 **설치된 스킨**에 넣은 뒤 바로 입혀요. 방문자 화면에는 30초쯤 안에 보여요. 되돌리려면 [[이전 스킨으로 되돌리기]]를 눌러요.",
    "care": "라이트·다크 말고 20개까지 둘 수 있어요. 같은 이름으로 직접 올린 스킨이 있으면 바꾸기 전에 물어봐요. **사이트를 업데이트하면 쓸 수 있어요.**가 붙은 스킨은 아직 적용할 수 없어요.",
