    "click": "https:// 로 시작하는 주소를 다 쓰고 칸 밖을 누르면 저절로 저장돼요. 방문자는 내 사이트의 \"링크\" 화면에서 모두 볼 수 있어요. aimusiclist.com 은 내 곡 옆에 작은 아이콘을 보여 줘요. 칸을 비우면 지워져요.",
