    "when": "가끔 들어와서 새 글을 읽고, 나쁜 글은 지워요.",
    "click": "아래 쪽 번호 버튼으로 지난 글을 봐요. 여기서 글을 고치거나 답할 수는 없고, 지우기만 할 수 있어요.",
    "care": "방문자는 이름 20자, 글 500자까지 쓸 수 있어요. 링크는 안 되고, 한 사람이 하루에 50개까지 쓸 수 있어요. 글은 내가 지우기 전까지 남아요. 방명록을 꺼도 남아요. **삭제된 곡**은 그 곡이 지워졌다는 뜻이에요.",
    "like": "가게 문 앞 메모장을 최신 장부터 넘겨 보는 거예요."
