    "click": "탭을 누르면 화면만 바뀌어요. 메뉴를 더하고, 고치고, 옮기고, 지우면 바로 저장돼요.",
    "care": "메뉴는 30개까지예요. 먼저 메인 장르를, 원하면 세부 장르를, 그다음 이름(30자까지, 안 넣어도 됨)을 정해요. aimusiclist.com 장르를 쓰니까 내 사이트와 aimusiclist.com 이 같은 기준으로 나뉘어요.",
    "like": "가게 선반의 이름표예요. '알앤비는 여기, 힙합은 저기.'"
