    "click": "누를 것은 없어요. 줄마다 이미 Top 100 안인지, 청취자가 몇 명쯤 더 필요한지, 거의 닿았는지 알려 줘요.",
    "care": "**짐작**이지 약속이 아니에요. 진짜 차트는 다른 것도 함께 보기 때문에, 가까워도 못 들어갈 수 있어요. Top 100 이 아직 다 차지 않았다면 진입 조건만 넘으면 들어가요.",
    "like": "등산로에 있는 \"정상까지 약 200걸음\" 표지판과 같아요."
