    "when": "이 칸 숫자가 이상해 보일 때 읽어요.",
    "care": "aimusiclist 는 **같은 사람은 하루에 한 번만** 세요. 그래도 한 사람이 여러 날 들으면 여러 번 세지니, 실제 청취자는 더 적을 수 있어요. 대략적인 길잡이로만 봐 주세요.",
    "like": "발자국 수로 몇 명이 왔는지 짐작하는 것과 같아요. 두 번 지나간 사람도 있으니까요."
